import axios from 'axios';
import React, { useState, useEffect, useRef } from 'react';
import { useParams, useSearchParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import PostCard from '../components/PostCard';
import api, { PEXELS_KEY } from '../api';

const SUGGESTIONS = ['Nature','Technology','Travel','Architecture','People','Food','Space','Art','Business','Fashion'];

function handleDownload(url, e) {
  e.stopPropagation();
  e.preventDefault();
  fetch(url)
    .then(function(res) { return res.blob(); })
    .then(function(blob) {
      var blobUrl = window.URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = blobUrl;
      a.download = 'inkwell-image.jpg';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(blobUrl);
    })
    .catch(function() { window.open(url, '_blank'); });
}

function PinCard(props) {
  var img = props.img;
  var onSelect = props.onSelect;
  var imgRef = useRef(null);
  var ratio = img.height / img.width;
  var pt = (ratio * 100).toFixed(2) + '%';

  useEffect(function() {
    if (imgRef.current && imgRef.current.complete) {
      imgRef.current.style.opacity = '1';
      imgRef.current.style.transform = 'translateY(0)';
    }
  }, []);

  return React.createElement(
    'div',
    {
      style: {
        position: 'relative',
        borderRadius: 16,
        overflow: 'hidden',
        cursor: 'pointer',
        background: '#f0f0f0',
        breakInside: 'avoid',
        marginBottom: 12,
        display: 'block',
        width: '100%',
        boxSizing: 'border-box',
      },
      className: 'pin-card',
      onClick: function() { onSelect(img); },
    },
    React.createElement(
      'div',
      { style: { position: 'relative', width: '100%', paddingTop: pt } },
      React.createElement('img', {
        ref: imgRef,
        src: img.src.medium,
        alt: img.alt,
        className: 'pin-img',
        style: {
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          objectFit: 'cover',
          display: 'block',
          borderRadius: 16,
          opacity: 0,
          transform: 'translateY(12px)',
          transition: 'opacity 0.5s ease, transform 0.5s ease',
        },
        onLoad: function() {
          if (imgRef.current) {
            imgRef.current.style.opacity = '1';
            imgRef.current.style.transform = 'translateY(0)';
          }
        },
      }),
      React.createElement(
        'div',
        {
          className: 'pin-overlay',
          style: {
            position: 'absolute',
            inset: 0,
            background: 'linear-gradient(to top, rgba(0,0,0,0.72) 0%, rgba(0,0,0,0.18) 55%, transparent 100%)',
            opacity: 0,
            transition: 'opacity 0.25s ease',
            display: 'flex',
            alignItems: 'flex-end',
            padding: '14px 12px',
            borderRadius: 16,
            pointerEvents: 'none',
          },
        },
        React.createElement(
          'span',
          {
            style: {
              fontSize: 12,
              color: '#fff',
              fontWeight: 600,
              letterSpacing: '0.01em',
              textShadow: '0 1px 4px rgba(0,0,0,0.6)',
            },
          },
          '\uD83D\uDCF7 ' + img.photographer
        )
      ),
      React.createElement(
        'button',
        {
          className: 'pin-dlbtn',
          style: {
            position: 'absolute',
            top: 10,
            right: 10,
            width: 40,
            height: 40,
            borderRadius: '50%',
            background: '#e30d10',
            color: '#fff',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            border: 'none',
            cursor: 'pointer',
            zIndex: 10,
            boxShadow: '0 2px 12px rgba(0,0,0,0.35)',
            fontSize: 18,
            fontWeight: 700,
            lineHeight: 1,
            transition: 'opacity 0.2s ease, transform 0.15s ease',
          },
          title: 'Download',
          onClick: function(e) { handleDownload(img.src.original, e); },
        },
        '\u2193'
      )
    )
  );
}



